INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S2-Q4$batch13$, 144, 2, 4, $batch13$Flaw$batch13$, $batch13$Biologist: A careful study of the behavior of six individual chameleons concluded that lizards such as chameleons bask in the sun not only for warmth but also to regulate their production of vitamin D. Critics of the study—although correct in observing that its sample size was very small—are wrong to doubt its results. After all, the study’s author is well regarded professionally and has been doing excellent work for years.$batch13$, $batch13$The reasoning in the biologist’s argument is most vulnerable to criticism on the grounds that the argument$batch13$, $batch13$C$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q4$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$takes the behavior of chameleons to be generalizable to lizards as a whole$batch13$, $batch13$Wrong Target$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$fails to explain how chameleons regulate their vitamin D production by basking in the sun$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$focuses its attention on the study’s author rather than on the study itself$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$fails to demonstrate that the study’s critics have relevant expertise$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$holds the study’s author to a higher standard than it holds the study’s critics$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$The critics are wrong to doubt the study's results.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$The study's author is well regarded and has done excellent work for years.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The critics doubt the study because its sample was tiny, and the biologist admits they're right about that. The defense is about the author's reputation. A good researcher can still run a study too small to support its conclusion.$batch13$), (3, $batch13$Goal$batch13$, $batch13$The argument defends the study by praising its author.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$That generalization is the study's conclusion. The biologist's own reasoning is about whether the critics should doubt it.$batch13$), ($batch13$B$batch13$, $batch13$The argument doesn't need to explain the mechanism.$batch13$), ($batch13$C$batch13$, $batch13$The author's reputation doesn't answer the sample-size problem. It sidesteps it.$batch13$), ($batch13$D$batch13$, $batch13$The biologist admits the critics are right about the sample size, so their expertise isn't the issue.$batch13$), ($batch13$E$batch13$, $batch13$The argument applies no standard to the critics at all.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S2-Q4$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
